import React, { useState, useEffect } from 'react';
import { Card, Avatar, Descriptions, List, Tabs, Button, Space, Tag } from 'antd';
import { UserOutlined, EditOutlined, SettingOutlined, FileTextOutlined, HeartOutlined } from '@ant-design/icons';
import { BlogPost } from '../Lib/typeDefinition';
import LikeButton from '../UI/LikeButton';

const { TabPane } = Tabs;

interface ProfileProps {
  userId?: number;
}

const Profile: React.FC<ProfileProps> = ({ userId = 1 }) => {
  const [userInfo, setUserInfo] = useState({
    id: 1,
    name: "John Doe",
    email: "john.doe@example.com",
    avatar: "",
    motto: "Code, Create, Inspire",
    joinDate: "2023-01-15",
    postsCount: 25,
    likesCount: 156
  });

  const [userPosts, setUserPosts] = useState<BlogPost[]>([]);
  const [likedPosts, setLikedPosts] = useState<BlogPost[]>([]);

  useEffect(() => {
    const mockUserPosts: BlogPost[] = [
      { id: 1, title: "My Journey with React", content: "Sharing my experience learning React...", likes: 23 },
      { id: 2, title: "TypeScript Tips and Tricks", content: "Some useful TypeScript patterns I've discovered...", likes: 15 },
      { id: 3, title: "Building Better UIs", content: "Principles for creating user-friendly interfaces...", likes: 31 }
    ];
    
    const mockLikedPosts: BlogPost[] = [
      { id: 4, title: "Advanced JavaScript Concepts", content: "Deep dive into closures and prototypes...", likes: 45 },
      { id: 5, title: "CSS Grid Layout Guide", content: "Complete guide to CSS Grid...", likes: 38 }
    ];

    setUserPosts(mockUserPosts);
    setLikedPosts(mockLikedPosts);
  }, [userId]);

  const handleEditProfile = () => {
    console.log('Edit profile clicked');
  };

  return (
    <div style={{ maxWidth: '1000px', margin: '0 auto' }}>
      <Card>
        <div style={{ display: 'flex', alignItems: 'center', marginBottom: '24px' }}>
          <Avatar 
            size={80} 
            icon={<UserOutlined />} 
            src={userInfo.avatar}
            style={{ marginRight: '24px' }}
          />
          <div style={{ flex: 1 }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>{userInfo.name}</h2>
            <p style={{ color: '#666', margin: '4px 0', fontStyle: 'italic' }}>
              "{userInfo.motto}"
            </p>
            <Space>
              <Tag color="blue">{userInfo.postsCount} Posts</Tag>
              <Tag color="red">{userInfo.likesCount} Likes Received</Tag>
            </Space>
          </div>
          <Button 
            type="primary" 
            icon={<EditOutlined />}
            onClick={handleEditProfile}
          >
            Edit Profile
          </Button>
        </div>

        <Descriptions bordered size="small">
          <Descriptions.Item label="Email">{userInfo.email}</Descriptions.Item>
          <Descriptions.Item label="Joined">{userInfo.joinDate}</Descriptions.Item>
          <Descriptions.Item label="User ID">{userInfo.id}</Descriptions.Item>
        </Descriptions>
      </Card>

      <Card style={{ marginTop: '24px' }}>
        <Tabs defaultActiveKey="posts">
          <TabPane 
            tab={
              <Space>
                <FileTextOutlined />
                My Posts ({userPosts.length})
              </Space>
            } 
            key="posts"
          >
            <List
              dataSource={userPosts}
              renderItem={(post) => (
                <List.Item
                  actions={[
                    <LikeButton 
                      key="like"
                      postId={post.id} 
                      initialLikes={post.likes} 
                    />,
                    <Button key="edit" type="text" size="small" icon={<EditOutlined />}>
                      Edit
                    </Button>
                  ]}
                >
                  <List.Item.Meta
                    title={post.title}
                    description={post.content}
                  />
                </List.Item>
              )}
            />
          </TabPane>

          <TabPane 
            tab={
              <Space>
                <HeartOutlined />
                Liked Posts ({likedPosts.length})
              </Space>
            } 
            key="liked"
          >
            <List
              dataSource={likedPosts}
              renderItem={(post) => (
                <List.Item
                  actions={[
                    <LikeButton 
                      key="like"
                      postId={post.id} 
                      initialLikes={post.likes} 
                      initialLiked={true}
                    />
                  ]}
                >
                  <List.Item.Meta
                    title={post.title}
                    description={post.content}
                  />
                </List.Item>
              )}
            />
          </TabPane>

          <TabPane 
            tab={
              <Space>
                <SettingOutlined />
                Settings
              </Space>
            } 
            key="settings"
          >
            <div style={{ padding: '24px', textAlign: 'center', color: '#666' }}>
              Settings panel coming soon...
            </div>
          </TabPane>
        </Tabs>
      </Card>
    </div>
  );
};

export default Profile;