import React, { useState } from 'react';
import { Button, Space, message } from 'antd';
import { LikeOutlined, LikeFilled } from '@ant-design/icons';

interface LikeButtonProps {
  postId: number;
  initialLikes?: number;
  initialLiked?: boolean;
  onLikeChange?: (postId: number, likes: number, liked: boolean) => void;
}

const LikeButton: React.FC<LikeButtonProps> = ({ 
  postId, 
  initialLikes = 0, 
  initialLiked = false,
  onLikeChange 
}) => {
  const [likes, setLikes] = useState(initialLikes);
  const [liked, setLiked] = useState(initialLiked);
  const [loading, setLoading] = useState(false);

  const handleLike = async () => {
    setLoading(true);
    
    try {
      const newLiked = !liked;
      const newLikes = newLiked ? likes + 1 : likes - 1;
      
      setLiked(newLiked);
      setLikes(newLikes);
      
      if (onLikeChange) {
        onLikeChange(postId, newLikes, newLiked);
      }
      
      message.success(newLiked ? 'Liked!' : 'Unliked!');
    } catch (error) {
      message.error('Failed to update like status');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button 
      type="text" 
      size="small"
      loading={loading}
      onClick={handleLike}
      icon={liked ? <LikeFilled style={{ color: '#1890ff' }} /> : <LikeOutlined />}
      style={{ 
        padding: '4px 8px',
        height: 'auto',
        color: liked ? '#1890ff' : undefined
      }}
    >
      <Space size={4}>
        <span>{likes}</span>
      </Space>
    </Button>
  );
};

export default LikeButton;