import React, { useState, useEffect } from 'react';
import { Card, List, Tag, Typography, Space } from 'antd';
import { FireOutlined, ClockCircleOutlined, TagsOutlined } from '@ant-design/icons';
import { BlogPost } from '../Lib/typeDefinition';

const { Title, Text } = Typography;

interface SidebarProps {
  posts?: BlogPost[];
}

const Sidebar: React.FC<SidebarProps> = ({ posts = [] }) => {
  const [popularPosts, setPopularPosts] = useState<BlogPost[]>([]);
  const [recentPosts, setRecentPosts] = useState<BlogPost[]>([]);

  useEffect(() => {
    if (posts.length > 0) {
      setPopularPosts(posts.slice(0, 5));
      setRecentPosts(posts.slice(-5).reverse());
    }
  }, [posts]);

  const mockTags = [
    { name: 'React', count: 12 },
    { name: 'JavaScript', count: 8 },
    { name: 'TypeScript', count: 6 },
    { name: 'Spring Boot', count: 4 },
    { name: 'Web Dev', count: 10 }
  ];

  return (
    <Space direction="vertical" size="middle" style={{ width: '100%' }}>
      <Card
        title={
          <Space>
            <FireOutlined />
            <span>Popular Posts</span>
          </Space>
        }
        size="small"
      >
        <List
          size="small"
          dataSource={popularPosts}
          renderItem={(post) => (
            <List.Item>
              <Text ellipsis style={{ cursor: 'pointer' }} title={post.title}>
                {post.title}
              </Text>
            </List.Item>
          )}
        />
      </Card>

      <Card
        title={
          <Space>
            <ClockCircleOutlined />
            <span>Recent Posts</span>
          </Space>
        }
        size="small"
      >
        <List
          size="small"
          dataSource={recentPosts}
          renderItem={(post) => (
            <List.Item>
              <Text ellipsis style={{ cursor: 'pointer' }} title={post.title}>
                {post.title}
              </Text>
            </List.Item>
          )}
        />
      </Card>

      <Card
        title={
          <Space>
            <TagsOutlined />
            <span>Popular Tags</span>
          </Space>
        }
        size="small"
      >
        <Space wrap>
          {mockTags.map((tag) => (
            <Tag key={tag.name} style={{ cursor: 'pointer' }}>
              {tag.name} ({tag.count})
            </Tag>
          ))}
        </Space>
      </Card>
    </Space>
  );
};

export default Sidebar;