import React, { useState, useEffect } from 'react';
import { Row, Col } from 'antd';
import PostGrid from '../UI/Post/PostGrid';
import MakePostComponent from '../UI/MakePostComponent';
import SearchBar from '../UI/SearchBar';
import Sidebar from '../UI/Sidebar';
import { BlogPost } from '../Lib/typeDefinition';

const Home: React.FC = () => {
  const [searchKeyword, setSearchKeyword] = useState('');
  const [posts, setPosts] = useState<BlogPost[]>([]);

  useEffect(() => {
    const mockPosts: BlogPost[] = [
      { id: 1, title: "Getting Started with React", content: "Learn the basics of React development", likes: 15 },
      { id: 2, title: "TypeScript Best Practices", content: "Tips for writing better TypeScript code", likes: 23 },
      { id: 3, title: "Spring Boot Tutorial", content: "Building REST APIs with Spring Boot", likes: 8 },
      { id: 4, title: "Web Development Trends", content: "Latest trends in web development", likes: 32 },
      { id: 5, title: "Database Design Patterns", content: "Common patterns for database design", likes: 19 }
    ];
    setPosts(mockPosts);
  }, []);

  const handleSearch = (keyword: string) => {
    setSearchKeyword(keyword);
  };

  return (
    <>
      <SearchBar onSearch={handleSearch} />
      <Row gutter={16}>
        <Col xs={24} lg={18}>
          <PostGrid searchKeyword={searchKeyword} />
          <MakePostComponent />
        </Col>
        <Col xs={0} lg={6}>
          <Sidebar posts={posts} />
        </Col>
      </Row>
    </>
  );
};

export default Home;